(async () => {
  const deadline = performance.now() + 60000;
  while (true) {
    const nuxt = document.querySelector('#__nuxt')?.__vue_app__?.config.globalProperties.$nuxt;
    const heading = document.querySelector('h1');
    if (nuxt?.isHydrating === false && heading?.textContent.trim() === 'Introduction' && heading.getBoundingClientRect().height > 0) break;
    if (performance.now() > deadline) throw new Error('Timed out waiting for hydration and Introduction: ' + JSON.stringify({url:location.href,readyState:document.readyState,heading:heading?.textContent,nuxt:!!nuxt,isHydrating:nuxt?.isHydrating}));
    await new Promise(resolve => setTimeout(resolve, 50));
  }
  const style = document.createElement('style');
  style.textContent = '#nuxt-devtools-container { display: none !important; } *, *::before, *::after { animation: none !important; transition: none !important; caret-color: transparent !important; }';
  document.head.append(style);
  await document.fonts.ready;
  await Promise.all([...document.images].map(image => image.decode().catch(() => {})));
  window.scrollTo(0, 0);
  await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  const state = {
    title: document.title,
    heading: document.querySelector('h1').textContent.trim(),
    viewport: [innerWidth, innerHeight, devicePixelRatio],
    theme: document.documentElement.className,
    fonts: document.fonts.status,
    hydrated: document.querySelector('#__nuxt').__vue_app__.config.globalProperties.$nuxt.isHydrating === false,
    overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    brokenImages: [...document.images].filter(image => !image.complete || !image.naturalWidth).map(image => image.getAttribute('src'))
  };
  if (state.overflow || state.brokenImages.length || state.theme.includes('dark') || state.viewport.join(',') !== '1440,1000,1') throw new Error(JSON.stringify(state));
  return state;
})()

