import http from 'node:http';
import {readFile,appendFile} from 'node:fs/promises';
const har=JSON.parse(await readFile('/bench/duxt.har','utf8'));
const entries=new Map();
const key=(method,url,body='')=>{const u=new URL(url,'http://localhost:3286');return `${method} ${u.pathname}${u.search} ${body}`;};
for(const e of har.log.entries){
  if(e.response.status<200 || e.response.status>=400 || e.response.status===304)continue;
  const body=Buffer.from(e.response.content.text||'',e.response.content.encoding==='base64'?'base64':'utf8');
  const headers=Object.fromEntries(e.response.headers.filter(h=>!['content-length','content-encoding','transfer-encoding','connection','set-cookie'].includes(h.name.toLowerCase())).map(h=>[h.name,h.value]));
  headers['content-length']=body.length;headers['cache-control']='public, max-age=31536000';
  entries.set(key(e.request.method,e.request.url,e.request.postData?.text),{status:e.response.status,headers,body});
}
const server=http.createServer(async(req,res)=>{
  const chunks=[];for await(const chunk of req)chunks.push(chunk);
  const requestKey=key(req.method,req.url,Buffer.concat(chunks).toString());
  const entry=entries.get(requestKey);
  if(!entry){await appendFile('/bench/results/replay-misses.log',requestKey+'\n');res.writeHead(404);res.end('Request missing from HAR');return;}
  res.writeHead(entry.status,entry.headers);res.end(entry.body);
});
server.on('upgrade',(_req,socket)=>socket.destroy());
server.listen(3286,'127.0.0.1',()=>console.log(`HAR replay ready: ${entries.size} frozen responses`));

import http from 'node:http';
import net from 'node:net';
const host = process.argv[2];
const server = http.createServer((req,res) => {
  const upstream = http.request({hostname:'127.0.0.1',port:3286,path:req.url,method:req.method,headers:{...req.headers,host:'127.0.0.1:3286'}},reply => {
    res.writeHead(reply.statusCode,reply.headers); reply.pipe(res);
  });
  upstream.on('error',error => {res.writeHead(502);res.end(error.message);});
  req.pipe(upstream);
});
server.on('upgrade',(req,socket,head) => {
  const upstream = net.connect(3286,'127.0.0.1',() => {
    upstream.write(`${req.method} ${req.url} HTTP/${req.httpVersion}\r\n`);
    for(const [key,value] of Object.entries(req.headers)) upstream.write(`${key}: ${key === 'host' ? '127.0.0.1:3286' : value}\r\n`);
    upstream.write('\r\n');upstream.write(head); socket.pipe(upstream);upstream.pipe(socket);
  });
  upstream.on('error',()=>socket.destroy());socket.on('error',()=>upstream.destroy());
});
server.listen(3287,host,() => console.log(`Benchmark proxy: http://${host}:3287`));

