import { performance } from 'node:perf_hooks';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
const [tool, countArg = '1', prefix = 'smoke'] = process.argv.slice(2);
const count = Number(countArg);
const started = performance.now();
const ready = await readFile('/bench/ready.js', 'utf8');
await mkdir('/bench/results', { recursive: true });
const args = ['--no-sandbox', '--disable-dev-shm-usage', '--lang=en-GB', '--force-device-scale-factor=1', '--no-proxy-server'];
const launchStart = performance.now();
const browser = tool === 'playwright'
  ? await (await import('playwright-core')).chromium.launch({ executablePath: '/browser/chrome', headless: true, args })
  : await (await import('puppeteer-core')).default.launch({ executablePath: '/browser/chrome', headless: true, args });
const launch_ms = performance.now() - launchStart;
const browserVersion = await browser.version();
const context = tool === 'playwright' ? await browser.newContext({ viewport: {width:1440,height:1000},deviceScaleFactor:1,locale:'en-GB',timezoneId:'UTC',colorScheme:'light',reducedMotion:'reduce' }) : browser.defaultBrowserContext();
const rows = [];
try {
  for (let index=0;index<count;index++) {
    const shotStart = performance.now();
    const page = await context.newPage();
    if (tool === 'puppeteer') {
      await page.setViewport({width:1440,height:1000,deviceScaleFactor:1});
      await page.emulateTimezone('UTC');
      await page.emulateMediaFeatures([{name:'prefers-color-scheme',value:'light'},{name:'prefers-reduced-motion',value:'reduce'}]);
    }
    const response = await page.goto(process.env.CAPTURE_URL, {waitUntil:'domcontentloaded', timeout:60000});
    if(response.status() !== 200) throw new Error(`HTTP ${response.status()}`);
    const state = await page.evaluate(ready);
    const readyAt = performance.now();
    const buffer = await page.screenshot({type:'png',fullPage:false});
    const capturedAt = performance.now();
    const path = `/bench/results/${prefix}-${tool}-${index}.png`;
    await writeFile(path,buffer);
    const writtenAt = performance.now();
    await page.close();
    const row = {tool,index,launch_ms,page_ready_ms:readyAt-shotStart,screenshot_ms:capturedAt-readyAt,write_ms:writtenAt-capturedAt,capture_ms:writtenAt-shotStart,bytes:buffer.length,sha256:createHash('sha256').update(buffer).digest('hex'),state,path};
    rows.push(row);
    console.log(JSON.stringify(row));
  }
} finally { await browser.close(); }
console.log(JSON.stringify({summary:true,tool,count,launch_ms,total_ms:performance.now()-started,browserVersion}));

