use headless_chrome::{Browser, LaunchOptionsBuilder};
use headless_chrome::protocol::cdp::{Emulation, Page, Runtime};
use serde_json::json;
use std::{ffi::OsStr, time::{Duration, Instant}};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let started = Instant::now();
    let count: usize = std::env::args().nth(1).unwrap_or("1".into()).parse()?;
    let prefix = std::env::args().nth(2).unwrap_or("smoke".into());
    std::fs::create_dir_all("/bench/results")?;
    let launch_start = Instant::now();
    let browser = Browser::new(LaunchOptionsBuilder::default()
        .path(Some("/browser/chrome".into())).sandbox(false).headless(true)
        .idle_browser_timeout(Duration::from_secs(120))
        .args(vec![OsStr::new("--hide-scrollbars"),OsStr::new("--disable-dev-shm-usage"),OsStr::new("--lang=en-GB"),OsStr::new("--force-device-scale-factor=1"),OsStr::new("--no-proxy-server")])
        .build()?)?;
    let launch_ms = launch_start.elapsed().as_secs_f64()*1000.;
    for index in 0..count {
        let shot_start = Instant::now();
        let tab = browser.new_tab()?;
        tab.call_method(serde_json::from_value::<Emulation::SetDeviceMetricsOverride>(json!({"width":1440,"height":1000,"deviceScaleFactor":1,"mobile":false}))?)?;
        tab.call_method(serde_json::from_value::<Emulation::SetEmulatedMedia>(json!({"features":[{"name":"prefers-color-scheme","value":"light"},{"name":"prefers-reduced-motion","value":"reduce"}]}))?)?;
        tab.call_method(serde_json::from_value::<Emulation::SetTimezoneOverride>(json!({"timezoneId":"UTC"}))?)?;
        tab.navigate_to(&std::env::var("CAPTURE_URL")?)?.wait_until_navigated()?;
        let result = tab.call_method(serde_json::from_value::<Runtime::Evaluate>(json!({"expression":include_str!("../../../ready.js"),"awaitPromise":true,"returnByValue":true}))?)?;
        if result.exception_details.is_some() { return Err(format!("Readiness failed: {:?}",result.exception_details).into()); }
        let state = result.result.value.ok_or("No state returned")?;
        let ready_at = shot_start.elapsed().as_secs_f64()*1000.;
        let bytes = tab.capture_screenshot(Page::CaptureScreenshotFormatOption::Png,None,None,true)?;
        let captured_at = shot_start.elapsed().as_secs_f64()*1000.;
        let path = format!("/bench/results/{prefix}-headless_chrome-{index}.png");
        std::fs::write(&path, &bytes)?;
        let written_at = shot_start.elapsed().as_secs_f64()*1000.;
        tab.close(true)?;
        println!("{}",json!({"tool":"headless_chrome","index":index,"launch_ms":launch_ms,"page_ready_ms":ready_at,"screenshot_ms":captured_at-ready_at,"write_ms":written_at-captured_at,"capture_ms":written_at,"bytes":bytes.len(),"state":state,"path":path}));
    }
    drop(browser);
    println!("{}",json!({"summary":true,"tool":"headless_chrome","count":count,"launch_ms":launch_ms,"total_ms":started.elapsed().as_secs_f64()*1000.}));
    Ok(())
}

